sql.where:
DELETED = 0

    AND ENTERPRISE_ID = #{enterpriseId}


    AND ENTERPRISE_NAME LIKE CONCAT('%', #{enterpriseName}, '%')


    AND ASSESSMENT_TYPE = #{assessmentType}


    AND ASSESSMENT_YEAR = #{assessmentYear}


    AND ASSESSMENT_QUARTER = #{assessmentQuarter}


    AND RISK_LEVEL = #{riskLevel}


    AND WARNING_STATUS = #{warningStatus}


    AND ASSESSMENT_STATUS = #{assessmentStatus}


    AND REVIEW_STATUS = #{reviewStatus}


    AND ASSESSMENT_DATE >= #{startDate}


    AND ASSESSMENT_DATE <= #{endDate}


    AND OVERALL_RISK_SCORE >= #{minRiskScore}


    AND OVERALL_RISK_SCORE <= #{maxRiskScore}

mapper.select:
SELECT COUNT(*) as totalAssessments, COUNT(CASE WHEN WARNING_STATUS = 'WARNING' THEN 1 END) as warningCount, COUNT(CASE WHEN RISK_LEVEL = 'HIGH' OR RISK_LEVEL = 'CRITICAL' THEN 1 END) as highRiskCount, COUNT(CASE WHEN ASSESSMENT_STATUS = 'COMPLETED' THEN 1 END) as completedCount, COUNT(CASE WHEN REVIEW_STATUS = 'PENDING' THEN 1 END) as pendingReviewCount, ROUND(AVG(OVERALL_RISK_SCORE), 2) as avgRiskScore, MAX(OVERALL_RISK_SCORE) as maxRiskScore, MIN(OVERALL_RISK_SCORE) as minRiskScore FROM TBL_RISK_ASSESSMENT WHERE DELETED = 0
AND ENTERPRISE_ID = #{enterpriseId}
AND ASSESSMENT_YEAR = #{assessmentYear}

SELECT RISK_LEVEL as riskLevel, COUNT(*) as count, ROUND(COUNT(*) * 100.0 / (SELECT COUNT(*) FROM TBL_RISK_ASSESSMENT WHERE DELETED = 0), 2) as percentage FROM TBL_RISK_ASSESSMENT WHERE DELETED = 0
AND ENTERPRISE_ID = #{enterpriseId}
AND ASSESSMENT_YEAR = #{assessmentYear}
GROUP BY RISK_LEVEL ORDER BY CASE RISK_LEVEL WHEN 'CRITICAL' THEN 1 WHEN 'HIGH' THEN 2 WHEN 'MEDIUM' THEN 3 WHEN 'LOW' THEN 4 ELSE 5 END
